import{z as T,x as B,o,c as d,q as r,j as s,D as e,d as t,s as i,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"FFT","description":"","frontmatter":{"title":"FFT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fft.md","filePath":"cs/fft.md","lastUpdated":1791063341000}'),p={name:"cs/fft.md"};function m(D,a,F,u,f,A){const l=B("Mermaid");return o(),d("div",null,[a[2]||(a[2]=r('<h1 id="fft" tabindex="-1">FFT <a class="header-anchor" href="#fft" aria-label="Permalink to &quot;FFT&quot;">​</a></h1><div class="epigraph"><p>多项式点值表示下乘法是逐点乘；DFT 把系数变成点值，$O(n\\log n)$ 而不是 $O(n^2)$ 的求值。</p><footer>—— 据 Cooley and Tukey, An Algorithm for the Machine Calculation of Complex Fourier Series, 1965；CLRS 第 30 章整理</footer></div><p>上一课<a href="/cs/karatsuba">Karatsuba</a>三次半长乘。多项式乘仍是卷积。缺口是 FFT：在单位根上求值与插值。不重写 Karatsuba 恒等式。后课 NTT 把复数换成模意义单位根。本课复数 DFT 的算法结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 次多项式系数乘：\\(c_k=\\sum_{i+j=k}a_i b_j\\)。点值：\\(C(\\omega^k)=A(\\omega^k)B(\\omega^k)\\)。DFT：\\(A(\\omega^k)=\\sum_j a_j \\omega^{jk}\\)。Cooley–Tukey：偶奇拆分，\\(T(n)=2T(n/2)+O(n)=O(n\\log n)\\)。卷积定理：循环卷积 = IDFT(DFT A · DFT B)。线性卷积把长度补到够，或补零。</p><p><span class="marginnote">数字实例：\\(n=1024\\) 时直接按定义做 DFT 要约 \\(1024^2 \\approx 100\\) 万次乘法；FFT 只需 \\(1024 \\times \\log_2 1024 = 1024 \\times 10\\) 约一万次蝶形运算——快了百倍。\\(n\\) 越大差距越悬殊，这就是「\\(n\\log n\\) 对 \\(n^2\\)」的具体分量。</span></p><p>缺口是蝶形，不是信号处理课的频谱物理。</p><h3 id="浮点误差" tabindex="-1">浮点误差 <a class="header-anchor" href="#浮点误差" aria-label="Permalink to &quot;浮点误差&quot;">​</a></h3><p>单位根是复数，浮点 FFT 乘大整数要选精度或改 NTT。本课算法正确性在精确算术；实现大数乘下一课。不要把数值噪声当卷积定义。</p><p><span class="marginnote">Cooley–Tukey 1965（Gauss 更早有同类分裂）。CLRS 30 写多项式 DFT。后课 NTT 服务精确卷积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 为 2 的幂。递归偶奇，或迭代位逆序 + 蝶形。逆变换：\\(\\omega^{-1}\\) 并除 \\(n\\)。卷积：补零到至少 \\(2n-1\\)。</p>',12)),(o(),s(E,null,{default:e(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COEF%5B%22%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20DFT%5B%22DFT%20O(n%20log%20n)%22%5D%0A%20%20DFT%20--%3E%20PT%5B%22%E9%80%90%E7%82%B9%E4%B9%98%22%5D%0A%20%20PT%20--%3E%20IDFT%5B%22IDFT%22%5D%0A%20%20IDFT%20--%3E%20CONV%5B%22%E5%8D%B7%E7%A7%AF%20%2F%20%E5%A4%9A%E9%A1%B9%E5%BC%8F%E4%B9%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"位逆序实现细节不挡主线。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"\\(\\omega^{n/2}=-1\\) 使偶奇拆分不重叠。与分治乘：都是 \\(O(n\\log n)\\) 与 \\(O(n^{1.585})\\) 的不同代数。圆周卷积有环绕，线性卷积须防。与矩阵：DFT 是 Vandermonde，直接乘 \\(O(n^2)\\)。",-1)),(o(),s(E,null,{default:e(()=>[i(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20N8%5B%228%20%E4%B8%AA%E7%B3%BB%E6%95%B0%20a0..a7%22%5D%20--%3E%20E%5B%22%E5%81%B6%E4%B8%8B%E6%A0%87%E7%BB%84%20a0%2Ca2%2Ca4%2Ca6%22%5D%0A%20%20N8%20--%3E%20O%5B%22%E5%A5%87%E4%B8%8B%E6%A0%87%E7%BB%84%20a1%2Ca3%2Ca5%2Ca7%22%5D%0A%20%20E%20--%3E%20E1%5B%22%E5%86%8D%E6%8B%86%20a0%2Ca4%22%5D%0A%20%20E%20--%3E%20E2%5B%22%E5%86%8D%E6%8B%86%20a2%2Ca6%22%5D%0A%20%20O%20--%3E%20O1%5B%22%E5%86%8D%E6%8B%86%20a1%2Ca5%22%5D%0A%20%20O%20--%3E%20O2%5B%22%E5%86%8D%E6%8B%86%20a3%2Ca7%22%5D%0A%20%20O2%20--%3E%20LEAF%5B%22%E5%8F%B6%E4%B8%BA%E5%8D%95%E7%82%B9%2C%20%E5%9B%9E%E7%A8%8B%E9%80%90%E5%B1%82%E8%9D%B6%E5%BD%A2%E5%90%88%E5%B9%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：\\(\\omega^{n/2} = -1\\) 的妙处像折纸剪纸——把纸对折（偶奇分组）后剪一刀，展开就是完全对称的两半。\\(\\pm k\\) 两处的求值共用同一批乘法结果，只差一个正负号，省下的正是朴素 DFT 里成倍重复的功。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Bluestein、不写实数打包全部技巧。不写卷积定理的连续傅里叶。后课默认：多项式乘可用 FFT \\(O(n\\log n)\\)（浮点）。下一课 NTT 精确模乘。</p><p><span class="marginnote">常见误区：初学者容易拿两个长度 \\(n\\) 的输入直接做 FFT 相乘再逆变换，以为得到的是普通乘积。长度不够时那是循环卷积——尾部会「绕回」叠到开头污染结果。要用 FFT 做普通乘法，必须先把两边补零到至少 \\(2n-1\\)，给结果留足位置。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DFT 求值 \\(O(n\\log n)\\)；卷积变逐点乘。</li><li>循环 vs 线性：补零。</li><li>大整数精确乘常改 NTT。</li><li>出处：Cooley and Tukey, 1965；CLRS 第 30 章。</li></ul>',6))])}const c=T(p,[["render",m]]);export{_ as __pageData,c as default};
